package com.jadhavr.erp.fee.controller; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.common.dto.PageResponse; import com.jadhavr.erp.fee.dto.*; import com.jadhavr.erp.fee.enums.FeeStructureStatus; import com.jadhavr.erp.fee.service.FeeService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/principal/fee-structures") public class FeeStructureController {private final FeeService s;public FeeStructureController(FeeService s){this.s=s;} @PostMapping public ResponseEntity<ApiResponse<FeeStructureResponse>> create(@Valid @RequestBody CreateFeeStructureRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Fee structure created successfully",s.createStructure(r)));}@GetMapping("/search") public ApiResponse<PageResponse<FeeStructureResponse>> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String academicYear,@RequestParam(required=false)FeeStructureStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size,@RequestParam(defaultValue="createdAt")String sortBy,@RequestParam(defaultValue="desc")String sortDir){return ApiResponse.success("Fee structures retrieved",s.searchStructures(keyword,collegeId,departmentId,academicYear,status,page,size,sortBy,sortDir));}@GetMapping("/{id}")public ApiResponse<FeeStructureResponse> get(@PathVariable Long id){return ApiResponse.success("Fee structure retrieved",s.getStructure(id));}@PutMapping("/{id}")public ApiResponse<FeeStructureResponse> update(@PathVariable Long id,@Valid @RequestBody UpdateFeeStructureRequest r){return ApiResponse.success("Fee structure updated",s.updateStructure(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> delete(@PathVariable Long id){s.deleteStructure(id);return ApiResponse.success("Fee structure deleted",null);}@PatchMapping("/{id}/activate")public ApiResponse<FeeStructureResponse> activate(@PathVariable Long id){return ApiResponse.success("Fee structure activated",s.setStructureStatus(id,FeeStructureStatus.ACTIVE));}@PatchMapping("/{id}/deactivate")public ApiResponse<FeeStructureResponse> deactivate(@PathVariable Long id){return ApiResponse.success("Fee structure deactivated",s.setStructureStatus(id,FeeStructureStatus.INACTIVE));}}
